window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-129d86627ba7fe40"]={"versions": [{"id": "FIG-129d86627ba7fe40", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion im Kommunikations-Stack der AUTOSAR Classic Platform. Das Diagramm modelliert einen Teilschritt der Bus-Off-Recovery-Zustandsmaschine zur Deaktivierung des Sendezweigs (TX) auf Ebene der CAN-Hardwareabstraktion.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Beteiligte BSW-Module:</li>\n<li><code>CanSM::CanSM</code> («module»): CAN State Manager als aufrufende Instanz.</li>\n<li><code>CanIf::CanIf</code> («module»): CAN Interface als ausführende Instanz.</li>\n<li>Schnittstellenaufruf:</li>\n<li>Synchroner Funktionsaufruf <code>CanIf_SetPduMode(CanController, PduModeRequest:=CANIF_SET_TX_OFFLINE)</code> mit Rückgabetyp <code>:Std_ReturnType</code>.</li>\n<li>Übergabeparameter: <code>CanController</code> (Identifikator des betroffenen CAN-Controllers) und <code>PduModeRequest</code> mit dem Enumerations-/Konstantenwert <code>CANIF_SET_TX_OFFLINE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Sequenz innerhalb eines kombinierten Interaktionsrahmens vom Typ <code>loop</code> mit der Bedingung <code>For every CAN controller assinged to this CAN network handle</code>.</li>\n<li><code>CanSM</code> iteriert über alle dem jeweiligen CAN-Netzwerk-Handle zugeordneten CAN-Controller.</li>\n<li>Für jeden Controller ruft <code>CanSM</code> synchron <code>CanIf_SetPduMode</code> mit dem Modus <code>CANIF_SET_TX_OFFLINE</code> am <code>CanIf</code> auf.</li>\n<li><code>CanIf</code> verarbeitet die Anforderung zur Abschaltung des TX-PDU-Modus und liefert das Ausführungsergebnis über eine synchrone Rückkehrnachricht (<code>:Std_ReturnType</code>) an <code>CanSM</code> zurück.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Vorgabe zur Isolation des Sendezweigs im Bus-Off-Wiederanlaufverfahren: Das Senden von Botschaften über die zugeordneten Controller wird blockiert, während der Empfangspfad unberührt bleibt.</li>\n<li>Implementierungshinweis: Der Aufruf erfolgt synchron pro Controller im Netz; Fehlerrückgaben des Typs <code>Std_ReturnType</code> (z. B. <code>E_NOT_OK</code>) müssen im Zustandsmaschinenablauf des CanSM entsprechend berücksichtigt werden. Im Diagramm existiert ein orthographischer Tippfehler im Guard-Ausdruck (<code>assinged</code> statt <code>assigned</code>).</li>\n</ul>"}, {"id": "FIG-8308c655970ecb4b", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion im Kommunikations-Stack der AUTOSAR Classic Platform. Das Diagramm modelliert einen Teilschritt der Bus-Off-Recovery-Zustandsmaschine zur Deaktivierung des Sendezweigs (TX) auf Ebene der CAN-Hardwareabstraktion.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Beteiligte BSW-Module:</li>\n<li><code>CanSM::CanSM</code> («module»): CAN State Manager als aufrufende Instanz.</li>\n<li><code>CanIf::CanIf</code> («module»): CAN Interface als ausführende Instanz.</li>\n<li>Schnittstellenaufruf:</li>\n<li>Synchroner Funktionsaufruf <code>CanIf_SetPduMode(CanController, PduModeRequest:=CANIF_SET_TX_OFFLINE)</code> mit Rückgabetyp <code>:Std_ReturnType</code>.</li>\n<li>Übergabeparameter: <code>CanController</code> (Identifikator des betroffenen CAN-Controllers) und <code>PduModeRequest</code> mit dem Enumerations-/Konstantenwert <code>CANIF_SET_TX_OFFLINE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Sequenz innerhalb eines kombinierten Interaktionsrahmens vom Typ <code>loop</code> mit der Bedingung <code>For every CAN controller assinged to this CAN network handle</code>.</li>\n<li><code>CanSM</code> iteriert über alle dem jeweiligen CAN-Netzwerk-Handle zugeordneten CAN-Controller.</li>\n<li>Für jeden Controller ruft <code>CanSM</code> synchron <code>CanIf_SetPduMode</code> mit dem Modus <code>CANIF_SET_TX_OFFLINE</code> am <code>CanIf</code> auf.</li>\n<li><code>CanIf</code> verarbeitet die Anforderung zur Abschaltung des TX-PDU-Modus und liefert das Ausführungsergebnis über eine synchrone Rückkehrnachricht (<code>:Std_ReturnType</code>) an <code>CanSM</code> zurück.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Vorgabe zur Isolation des Sendezweigs im Bus-Off-Wiederanlaufverfahren: Das Senden von Botschaften über die zugeordneten Controller wird blockiert, während der Empfangspfad unberührt bleibt.</li>\n<li>Implementierungshinweis: Der Aufruf erfolgt synchron pro Controller im Netz; Fehlerrückgaben des Typs <code>Std_ReturnType</code> (z. B. <code>E_NOT_OK</code>) müssen im Zustandsmaschinenablauf des CanSM entsprechend berücksichtigt werden. Im Diagramm existiert ein orthographischer Tippfehler im Guard-Ausdruck (<code>assinged</code> statt <code>assigned</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-129d86627ba7fe40", "to": "FIG-8308c655970ecb4b", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
